<script setup>
import { ref, watch } from 'vue';
import ToolIntro from '../../components/ToolIntro.vue';
import { generateRandom } from '../../utils/developerTools.js';
import { copyWithFeedback } from '../../utils/clipboard.js';
const mode = ref('uuid'), count = ref(10), length = ref(20), groups = ref(['lower','upper','digits','symbols']), min = ref(0), max = ref(100), uppercase = ref(false), hyphens = ref(true);
const output = ref(''), error = ref('');
watch([mode,count,length,groups,min,max,uppercase,hyphens], () => { output.value = ''; error.value = ''; });
function generate() { error.value = ''; output.value = ''; try { let values = generateRandom({ mode: mode.value, count: count.value, length: length.value, groups: groups.value, min: min.value, max: max.value }); if (mode.value === 'uuid') values = values.map(value => { if (!hyphens.value) value = value.replaceAll('-', ''); return uppercase.value ? value.toUpperCase() : value; }); output.value = values.join('\n'); } catch (e) { error.value = e.message; } }
generate();
</script>
<template><section><ToolIntro title="UUID / 随机生成器" eyebrow="DEVELOPER / RANDOM" description="生成 UUID、随机字符串与密码，批量准备开发所需的数据。" /><div class="utility-grid"><section class="panel utility-panel utility-stack"><label class="utility-field">生成类型<a-select v-model:value="mode" aria-label="随机生成类型" :options="[{value:'uuid',label:'UUID v4'},{value:'string',label:'随机字符串'},{value:'password',label:'随机密码'},{value:'number',label:'随机整数'}]" /></label><label class="utility-field">生成数量（1–500）<a-input-number v-model:value="count" :min="1" :max="500" :precision="0" aria-label="生成数量" /></label><div v-if="mode === 'uuid'" class="utility-toolbar"><a-checkbox v-model:checked="uppercase">大写</a-checkbox><a-checkbox v-model:checked="hyphens">保留连字符</a-checkbox></div><template v-if="mode === 'string' || mode === 'password'"><label class="utility-field">字符长度（4–256）<a-input-number v-model:value="length" :min="4" :max="256" :precision="0" aria-label="随机字符长度" /></label><a-checkbox-group v-model:value="groups" :options="[{value:'lower',label:'小写字母'},{value:'upper',label:'大写字母'},{value:'digits',label:'数字'},{value:'symbols',label:'特殊符号'}]" /><p class="utility-note">密码模式保证每条结果包含所有选中的字符类型。</p></template><div v-if="mode === 'number'" class="utility-controls"><label class="utility-field">最小值<a-input-number v-model:value="min" :precision="0" aria-label="随机最小值" /></label><label class="utility-field">最大值（包含）<a-input-number v-model:value="max" :precision="0" aria-label="随机最大值" /></label></div><a-button type="primary" @click="generate">生成随机结果</a-button><p class="utility-note">使用浏览器 Web Crypto 生成随机数，内容不保存。随机整数和字符串可能重复。</p></section><section class="panel utility-panel"><div class="panel-heading"><h2>生成结果</h2><a-button :disabled="!output" @click="copyWithFeedback(output, '生成结果已复制。')">复制全部</a-button></div><a-alert v-if="error" :message="error" type="error" role="alert" /><pre v-if="output" class="utility-output utility-code">{{ output }}</pre><div v-else-if="!error" class="utility-empty">选择参数后点击生成</div></section></div></section></template>
